/* eslint-disable no-restricted-globals */

import { clientsClaim } from 'workbox-core';
import { ExpirationPlugin } from 'workbox-expiration';
import { precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { BackgroundSyncPlugin } from 'workbox-background-sync';

clientsClaim();

// Precache all of the assets generated by your build process.
precacheAndRoute(self.__WB_MANIFEST || []);

// Set up App Shell-style routing
const fileExtensionRegexp = new RegExp('/[^/?]+\\.[^/]+$');
registerRoute(
    // Return false to exempt requests from being fulfilled by index.html.
    ({ request, url }) => {
        // If this isn't a navigation, skip.
        if (request.mode !== 'navigate') return false;
        // If this is a URL that starts with /_, skip.
        if (url.pathname.startsWith('/_')) return false;
        // If this looks like a URL for a resource, because it contains a file extension, skip.
        if (url.pathname.match(fileExtensionRegexp)) return false;
        // Return true to signal that we want to use the handler.
        return true;
    },
    createHandlerBoundToURL(process.env.PUBLIC_URL + '/index.html')
);

// Cache API GET requests with NetworkFirst strategy
registerRoute(
    ({ url }) => url.pathname.startsWith('/api/') && !url.pathname.includes('/auth/'),
    new NetworkFirst({
        cacheName: 'api-cache',
        plugins: [
            new ExpirationPlugin({
                maxEntries: 50,
                maxAgeSeconds: 24 * 60 * 60, // 24 hours
            }),
        ],
    })
);

// Background Sync for Offline Mutations (Attendance, Leave, etc.)
const bgSyncPlugin = new BackgroundSyncPlugin('offline-mutations-queue', {
    maxRetentionTime: 24 * 60, // Retry for max of 24 Hours (specified in minutes)
});

registerRoute(
    ({ request, url }) => request.method === 'POST' || request.method === 'PUT',
    new NetworkFirst({ // Using NetworkFirst here, but it triggers bgSync on failure
        plugins: [bgSyncPlugin]
    }),
    'POST'
);

registerRoute(
    ({ request, url }) => request.method === 'POST' || request.method === 'PUT',
    new NetworkFirst({
        plugins: [bgSyncPlugin]
    }),
    'PUT'
);

// Listen to message for skip waiting
self.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
        self.skipWaiting();
    }
});
